var state={open:false,view:'list',kind:'',active:null,social:[],supportUnread:0,search:'',poll:null,threadPoll:null,busy:false,supportSig:'',socialSig:'',threadToken:0,recorder:null,recordStream:null,recordChunks:[],objectUrls:[],messageIndex:{support:{},social:{}}};
var el={};
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
