function time(v){var d=utc(v);if(!d)return'';try{return new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(d)}catch(_e){return d.toLocaleTimeString()}}
function getCore(){if(window.REBClientCore&&window.REBClientCore.json)core=window.REBClientCore;return core}
