function deletedKey(scope){return 'REB_CHAT_DELETED_V86_'+cacheUser().replace(/[^a-z0-9_.-]+/gi,'_')+'_'+String(scope||'global')}
function deletedMap(scope){try{return JSON.parse(localStorage.getItem(deletedKey(scope))||'{}')||{}}catch(_e){return{}}}
