function msgDeleted(m,scope){if(!m)return false;var id=String(m.message_id||m.id||'');if(m.deleted_at||m.is_deleted||m.deleted||m.status==='deleted')return true;return !!(id&&deletedMap(scope)[id])}
function markDeleted(m,scope){var id=String(m&&(m.message_id||m.id)||'');if(!id)return;var d=deletedMap(scope);d[id]={id:id,created_at:m.created_at||new Date().toISOString(),mine:true};deletedSave(scope,d)}
function unmarkDeleted(m,scope){var id=String(m&&(m.message_id||m.id)||'');if(!id)return;var d=deletedMap(scope);delete d[id];deletedSave(scope,d)}
function mergeDeleted(list,scope,idField){var d=deletedMap(scope),seen={};(list||[]).forEach(function(m){seen[String(m[idField]||m.id||'')]=1});Object.keys(d).forEach(function(id){if(!seen[id]){var x={created_at:d[id].created_at||'',_deleted_local:true};x[idField]=id;if(idField==='message_id')x.viewer_is_sender=true;else x.sender_type='user';list.push(x)}});list.sort(function(a,b){var da=utc(a.created_at),db=utc(b.created_at);return (da?da.getTime():0)-(db?db.getTime():0)});return list}
function miniDeletedCopy(m,mine){return '<span class="reb-hc-mini-deleted-copy">'+esc(mine?'You deleted a message':'This message was deleted')+'</span>'}
function miniMeta(m,mine,deleted){return esc(time(m.created_at))+(m.edited_at&&!deleted?' · Edited':'')}
function miniActions(kind,m,mine,deleted){if(!mine||deleted||m._pending)return'';var id=String(kind==='support'?(m.id||m.message_id||''):(m.message_id||m.id||''));if(!id)return'';return '<button type="button" class="reb-hc-mini-msg-more" data-mini-more data-kind="'+esc(kind)+'" data-message-id="'+esc(id)+'" title="Message options" aria-label="Message options"><span class="reb-hc-mini-more-glyph" aria-hidden="true">⋯</span></button><div class="reb-hc-mini-msg-menu" data-mini-menu hidden><button type="button" data-mini-edit><i class="far fa-edit"></i><span>Edit</span></button><button type="button" class="danger" data-mini-delete><i class="far fa-trash-alt"></i><span>Delete</span></button></div>'}
function replaceMiniRow(row,html){if(!row||!row.isConnected)return;var w=document.createElement('div');w.innerHTML=html;var n=w.firstElementChild;if(n)row.replaceWith(n);hydrateSupportMedia()}
async function editMiniMessage(kind,id,row){var map=state.messageIndex[kind]||{},m=map[String(id)];if(!m)return;var old=String(kind==='support'?(m.message_text||''):(m.content||''));var hasMedia=kind==='support'?!!m.attachment:!!(m.media&&m.media.length);var value=prompt(hasMedia?'Edit message / media caption':'Edit message',old);if(value===null)return;value=String(value).trim();if(!value&&!hasMedia){toast('Message text cannot be empty.');return}try{var d;if(kind==='social'){d=await api('/api/social/messages/messages/'+encodeURIComponent(id),{method:'PATCH',json:{content:value},timeoutMs:10000});Object.assign(m,d.message||{content:value,edited_at:new Date().toISOString()});replaceMiniRow(row,socialMessageHtml(m));setTimeout(function(){loadSocial(true)},0)}else{d=await api('/api/customer-chat/messages/'+encodeURIComponent(id),{method:'PATCH',json:{message:value},timeoutMs:10000});Object.assign(m,d.message||{message_text:value,edited_at:new Date().toISOString()});replaceMiniRow(row,supportMessageHtml(m));setTimeout(function(){loadSupport(true,true)},0)}toast('Message edited.')}catch(e){toast((e&&e.message)||'Unable to edit message.') }}
async function deleteMiniMessage(kind,id,row){var map=state.messageIndex[kind]||{},m=map[String(id)];if(!m||!confirm('Delete this message? You will not be able to restore it.'))return;var scope=kind==='support'?'support':'social:'+String(state.active&&state.active.conversation_id||'');markDeleted(m,scope);var tomb=Object.assign({},m,{_deleted_local:true,deleted_at:new Date().toISOString()});replaceMiniRow(row,kind==='support'?supportMessageHtml(tomb):socialMessageHtml(tomb));try{if(kind==='social')await api('/api/social/messages/messages/'+encodeURIComponent(id),{method:'DELETE',timeoutMs:10000});else await api('/api/customer-chat/messages/'+encodeURIComponent(id),{method:'DELETE',timeoutMs:10000});toast('Message deleted.');setTimeout(function(){kind==='support'?loadSupport(true,true):loadSocial(true)},0)}catch(e){unmarkDeleted(m,scope);toast((e&&e.message)||'Unable to delete message.');setTimeout(function(){kind==='support'?loadSupport(false,true):loadSocial(false)},0)}}
function miniActionClick(e){var more=e.target.closest('[data-mini-more]');if(more){e.stopPropagation();var row=more.closest('.reb-hc-mini-message'),menu=row&&row.querySelector('[data-mini-menu]');el.messages.querySelectorAll('[data-mini-menu]').forEach(function(x){if(x!==menu)x.hidden=true});if(menu)menu.hidden=!menu.hidden;return}var edit=e.target.closest('[data-mini-edit]'),del=e.target.closest('[data-mini-delete]');if(!edit&&!del)return;var row=(edit||del).closest('.reb-hc-mini-message'),moreBtn=row&&row.querySelector('[data-mini-more]');if(!row||!moreBtn)return;var kind=moreBtn.dataset.kind,id=moreBtn.dataset.messageId,menu=row.querySelector('[data-mini-menu]');if(menu)menu.hidden=true;if(edit)editMiniMessage(kind,id,row);else deleteMiniMessage(kind,id,row)}
function fmtBytes(n){n=Number(n||0);if(!n)return'';if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
function setAvatar(node,p,kind){node.innerHTML='';node.className='reb-hc-mini-avatar'+(kind?' '+kind:'');if(kind==='support'){node.innerHTML='<i class="fas fa-headset"></i>';return}if(kind==='community'){node.innerHTML='<i class="fas fa-users"></i>';return}var name=String(p&&(p.display_name||p.username)||'ReachEmpire Member');var url=String(p&&p.avatar||'');if(!url){node.textContent=initials(name);return}var img=document.createElement('img');img.alt=name;img.src=url;img.onerror=function(){node.innerHTML='';node.textContent=initials(name)};node.appendChild(img);if(p&&p.online){var dot=document.createElement('i');dot.className='reb-hc-mini-online';node.appendChild(dot)}}
