function totalUnread(){return state.supportUnread+state.social.reduce(function(n,c){return n+Number(c.unread||0)},0)}
function syncBadge(){var n=totalUnread();el.badge.textContent=n>99?'99+':String(n);el.badge.hidden=n<=0}
